const BASE = "https://n8n.srv849680.hstgr.cloud/webhook";
const VOICE = "alice";
const LANG = "en-AU";

/** XML-escape. Brand names carry apostrophes; an unescaped one breaks the TwiML. */
function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

/** Build a callback URL, escaped for use inside a TwiML attribute. */
function cb(pathName, site, extra) {
  const u = BASE + "/" + pathName + "?site=" + encodeURIComponent(site) +
    "&k=" + encodeURIComponent(secret()) + (extra || "");
  return esc(u);
}

function secret() {
  let s;
  try { s = $env.LEADGEN_CALL_SECRET; } catch (e) { s = undefined; }
  if (!s) {
    throw new Error(
      "LEADGEN_CALL_SECRET is not readable from this n8n instance. Set it in the " +
      "n8n container env and ensure N8N_BLOCK_ENV_ACCESS_IN_NODE is not true."
    );
  }
  return s;
}

/**
 * Reject anything that is not Twilio calling our URL.
 *
 * The shared secret rides in the query string, which only Twilio and this
 * workflow ever see. Without it, anyone who guesses the webhook path can make
 * the account dial arbitrary numbers at our expense.
 */
function guard(q) {
  if (!q || q.k !== secret()) { throw new Error("rejected: bad or missing webhook secret"); }
}

function routeFor(q) {
  guard(q);
  const r = ROUTES[q.site];
  if (!r) { throw new Error("rejected: unknown site \"" + (q && q.site) + "\""); }
  return r;
}

function say(text) {
  return '<Say voice="' + VOICE + '" language="' + LANG + '">' + esc(text) + "</Say>";
}

function fill(tpl, brand) { return tpl.replace(/\{brand\}/g, brand); }

function twiml(inner) {
  return '<?xml version="1.0" encoding="UTF-8"?><Response>' + inner + "</Response>";
}

const COPY = {
  "consent": "Thanks for calling {brand}. Connecting you now.",
  "consentRecorded": "Thanks for calling {brand}. This call may be recorded for quality. Connecting you now.",
  "whisper": "New lead from {brand}.",
  "whisperRecorded": "New lead from {brand}. This call is recorded.",
  "voicemail": "Sorry, we could not take your call. Please leave your name, suburb and what you need after the beep, and we will call you straight back.",
  "voicemailThanks": "Thanks. We will be in touch shortly."
};

const q = $json.query || {};
const b = $json.body || {};
const r = routeFor(q);

// Pass the caller's own number through as caller ID so whoever answers can
// redial the customer straight from their call history. If the caller withheld
// it, fall back to the tracking number — a dial with no caller ID is rejected.
const callerId = (b.From && String(b.From).startsWith("+")) ? b.From : b.To;

const dialAttrs = [
  'callerId="' + esc(callerId) + '"',
  'timeout="18"',
  // answerOnBridge keeps the caller hearing real ringing while the whisper
  // plays to the other end, and stops billing/recording before a human answers.
  'answerOnBridge="true"',
  'action="' + cb("leadgen-call-complete", q.site, "") + '"',
  'method="POST"',
];
if (r.record) {
  dialAttrs.push('record="record-from-answer-dual"');
  dialAttrs.push('recordingStatusCallback="' + cb("leadgen-recording", q.site, "&kind=call") + '"');
  dialAttrs.push('recordingStatusCallbackEvent="completed"');
  dialAttrs.push('recordingStatusCallbackMethod="POST"');
}

const consent = fill(r.record ? COPY.consentRecorded : COPY.consent, r.brand);
const inner =
  say(consent) +
  "<Dial " + dialAttrs.join(" ") + ">" +
    '<Number url="' + cb("leadgen-whisper", q.site, "") + '" method="POST">' +
      esc(r.forwardTo) +
    "</Number>" +
  "</Dial>";

return [{ json: { twiml: twiml(inner), site: q.site, callSid: b.CallSid || "", from: b.From || "" } }];

