if (q.stage === "vm-done") {
  return [{ json: { twiml: twiml(say(COPY.voicemailThanks) + "<Hangup/>"), alert: "", site: q.site } }];
}

const status = b.DialCallStatus || "";
const duration = Number(b.DialCallDuration || 0);

if (status === "completed" || status === "answered") {
  return [{ json: { twiml: twiml("<Hangup/>"), alert: "", site: q.site, duration } }];
}

// Nobody picked up. Take a message ourselves rather than letting the forward
